// CSV exports. User-controlled text is neutralized against spreadsheet formula injection;
// numeric columns are generated by the app from integers and written unchanged.
import { toCsv, num } from '../domain/csv.js';
import { toDecimal } from '../domain/money.js';
import { idx, salesCohort, receiptActivity, activeAllocations } from '../domain/calc.js';
import { ISSUE_TYPES } from '../domain/issues.js';

const n = (c) => (c === null || c === undefined ? '' : num(toDecimal(c)));

export function salesCsv(state, range, cutoff) {
  const rows = salesCohort(state, range, cutoff).rows.map((r) => [r.sale.sourceId, r.sale.date, n(r.originalDue), n(r.credit), n(r.netDue), n(r.allocated), n(r.refunded), n(r.netAllocated), n(r.outstanding), n(r.liability), r.status, r.sale.claimedStatus, r.sale.customerLabel, r.sale.expectedAccount, r.sale.expectedReference, r.sale.dueDate, r.sale.notes]);
  return toCsv(['sale_id', 'sale_date', 'original_due', 'credited', 'net_due', 'allocated', 'refunded', 'net_allocated', 'outstanding', 'refund_liability', 'status', 'claimed_payment_status', 'customer_label', 'expected_account', 'expected_reference', 'due_date', 'notes'], rows);
}
export function receiptsCsv(state, range) {
  const rows = receiptActivity(state, range).rows.map((r) => [r.receipt.sourceId, r.receipt.receivedAt, r.receipt.date, r.receipt.accountId, n(r.receipt.gross), n(r.receipt.fee), n(r.receipt.net), n(r.allocated), n(r.available), r.receipt.reference, r.receipt.saleSourceId, r.receipt.notes]);
  return toCsv(['receipt_id', 'received_at', 'business_date', 'account_id', 'gross', 'fee', 'net', 'allocated', 'unapplied', 'reference', 'sale_id', 'notes'], rows);
}
export function allocationsCsv(state, range) {
  const { salesById, receiptsById } = idx(state);
  const rows = activeAllocations(state).filter((a) => { const d = receiptsById.get(a.receiptId).date; return d >= range.from && d <= range.to; })
    .map((a) => { const r = receiptsById.get(a.receiptId); const s = salesById.get(a.saleId); return [r.sourceId, r.accountId, r.date, s.sourceId, s.date, n(a.amount), a.method === 'MANUAL' ? 'Manually allocated' : 'Matched from imported records', a.reason, a.createdAt]; });
  return toCsv(['receipt_id', 'account_id', 'receipt_date', 'sale_id', 'sale_date', 'amount', 'method', 'reason', 'created_at'], rows);
}
export function issuesCsv(issues) {
  return toCsv(['type', 'date', 'summary', 'detail', 'amount', 'review_state', 'note'], issues.map((i) => [ISSUE_TYPES[i.type] || i.type, i.date || '', i.title, i.detail || '', n(i.amount), i.state || 'OPEN', i.note || '']));
}
